FontColorConditionFormulas.Color:
// Esta fórmula de formato condicional debe devolver uno de los siguientes Constantes de color:
// 
// Color (red, green, blue)
// crBlack
// crMaroon
// crGreen
// crOlive
// crNavy
// crPurple
// crTeal
// crSilver
// crRed
// crLime
// crYellow
// crBlue
// crFuchsia
// crAqua
// crWhite
// crNoColor
// 
IIF ({Productos_csv.Suspendido}="true",crRed ,crBlack )

ObjectFormatConditionFormulas.HorizontalAlignment:
// Esta fórmula de formato condicional debe devolver uno de los siguientes Constantes de alineación horizontal:
// Si está establecido, dejará de aplicarse el alineado horizontal del Objeto de informe y Párrafo (objeto de texto).
// 
// crDefaultHorAligned
// crLeftAligned
// crCenteredHorizontally
// crRightAligned
// crJustified
// 
IIF ({Productos_csv.Suspendido}="true",crRightAligned ,crLeftAligned )
